#define MOD 998244353

typedef struct {
    int x, d;
} Robot;

int cmp(const void *a, const void *b) {
    return ((Robot*)a)->x - ((Robot*)b)->x;
}

int main() {
    int n;
    scanf("%d", &n);
    Robot *robots = malloc(n * sizeof(Robot));
    for (int i = 0; i < n; i++) {
        scanf("%d %d", &robots[i].x, &robots[i].d);
    }
    qsort(robots, n, sizeof(Robot), cmp);

    int *reach = malloc(n * sizeof(int));
    int *dp = malloc((n + 1) * sizeof(int));

    // reach[i] = smallest index that robot i cannot reach (exclusive upper bound)
    int stack_top = -1;
    int *stack = malloc(n * sizeof(int));

    for (int i = n - 1; i >= 0; i--) {
        int limit = robots[i].x + robots[i].d;
        reach[i] = i + 1;
        while (stack_top >= 0 && robots[stack[stack_top]].x < limit) {
            if (reach[stack[stack_top]] > reach[i]) {
                reach[i] = reach[stack[stack_top]];
            }
            stack_top--;
        }
        stack[++stack_top] = i;
    }

    dp[n] = 1;
    for (int i = n - 1; i >= 0; i--) {
