#define MOD 998244353LL

typedef long long ll;

int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll*)a;
    ll y = *(const ll*)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

typedef struct {
    ll x, d;
} Robot;

int cmp_robot(const void *a, const void *b) {
    const Robot *ra = (const Robot*)a;
    const Robot *rb = (const Robot*)b;
    if (ra->x < rb->x) return -1;
    if (ra->x > rb->x) return 1;
    return 0;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    Robot *r = (Robot*)malloc(sizeof(Robot) * N);
    for (int i = 0; i < N; i++) scanf("%lld", &r[i].x);
    for (int i = 0; i < N; i++) scanf("%lld", &r[i].d);

    qsort(r, N, sizeof(Robot), cmp_robot);

    ll *X = (ll*)malloc(sizeof(ll) * N);
    ll *D = (ll*)malloc(sizeof(ll) * N);
    for (int i = 0; i < N; i++) {
        X[i] = r[i].x;
        D[i] = r[i].d;
    }

    /* nxt[i]: first index not removed if we activate robot i alone initially,
       considering chain reactions. Thus interval [i, nxt[i)-1] is removed. */
    int *nxt = (int*)malloc(sizeof(int) * N);

    /* Compute from right to left.
       Let reach = X[i] + D[i].
       All robots with position < reach are directly triggered.
       But each such robot j removes up to nxt[j]-1, so we merge intervals greedily. */
    for (int i = N - 1; i >= 0; i--) {
        ll reach = X[i] + D[i];

        int l = i + 1, rr = N;
        while (l < rr) {
            int m = (l + rr) >> 1;
            if (X[m] < reach) l = m + 1;
            else rr = m;
        }
        int cur = l; /* direct upper bound */

        int p = i + 1;
        while (p < cur) {
            if (nxt[p] > cur) cur = nxt[p];
            p = nxt[p];
        }
        nxt[i] = cur;
    }

    /* dp[i] = number of possible remaining sets considering robots i..N-1 */
    ll *dp = (ll*)malloc(sizeof(ll) * (N + 1));
    dp[N] = 1;

    for (int i = N - 1; i >= 0; i--) {
        /* Either keep robot i forever (do not activate any chain removing it now),
           or eventually activate some robot in the component starting at i, which
           removes all robots in [i, nxt[i)-1]. */
        dp[i] = dp[i + 1] + dp[nxt[i]];
        if (dp[i] >= MOD) dp[i] -= MOD;
    }

    printf("%lld\n", dp[0] % MOD);

    free(r);
    free(X);
    free(D);
    free(nxt);
    free(dp);
    return 0;
}

